<template>   <div class="cost-report-page">     <!-- 椤靛ご -->     <ContentWrap class="page-header-card">       <div class="page-header">         <div class="page-header__main">           <div class="page-header__title">浜у搧鎴愭湰鍒嗘瀽鎶ヨ〃</div>         </div>         <div class="page-header__actions">           <el-button :loading="loading" @click="loadData">             <Icon icon="ep:refresh" class="mr-5px" /> 鍒锋柊           </el-button>         </div>       </div>     </ContentWrap>      <!-- 绛涢€夊尯 -->     <ContentWrap class="filter-card">       <div class="filter-header">         <div class="filter-header__title">绛涢€夋潯浠?/div>       </div>       <el-form :model="queryParams" label-width="88px" class="filter-form" @submit.prevent>         <div class="filter-grid">           <el-form-item label="浜у搧">             <el-select               v-model="queryParams.productId"               placeholder="璇烽€夋嫨浜у搧"               filterable               clearable               class="!w-full"               @change="handleQuery"             >               <el-option                 v-for="item in productOptions"                 :key="item.productId"                 :label="item.productName || `浜у搧${item.productId}`"                 :value="item.productId"               />             </el-select>           </el-form-item>           <el-form-item label="寮€濮嬫湀浠?>             <el-date-picker               v-model="queryParams.startMonth"               type="month"               value-format="YYYY-MM"               placeholder="寮€濮嬫湀浠?               class="!w-full"               @change="handleQuery"             />           </el-form-item>           <el-form-item label="缁撴潫鏈堜唤">             <el-date-picker               v-model="queryParams.endMonth"               type="month"               value-format="YYYY-MM"               placeholder="缁撴潫鏈堜唤"               class="!w-full"               @change="handleQuery"             />           </el-form-item>           <el-form-item label="鍒嗘瀽缁村害">             <el-select v-model="queryParams.dimension" class="!w-full" @change="handleQuery">               <el-option label="鎸夋湀鍒嗘瀽" value="month" />               <el-option label="鎸夊鍒嗘瀽" value="quarter" />             </el-select>           </el-form-item>         </div>         <div class="filter-actions">           <el-button type="primary" :loading="loading" @click="handleQuery">             <Icon icon="ep:search" class="mr-5px" /> 鏌ヨ           </el-button>           <el-button @click="resetQuery">             <Icon icon="ep:refresh-left" class="mr-5px" /> 閲嶇疆           </el-button>         </div>       </el-form>     </ContentWrap>      <!-- 鍥捐〃鍖?-->     <div class="chart-grid">       <!-- 瓒嬪娍鍥?-->       <ContentWrap class="chart-card">         <div class="chart-header">           <div class="chart-header__title">鎴愭湰瓒嬪娍鍒嗘瀽</div>           <div class="chart-header__desc">灞曠ず浜у搧鎴愭湰闅忔椂闂村彉鍖栬秼鍔?/div>         </div>         <div class="chart-container">           <div ref="trendChartRef" class="chart-instance"></div>         </div>       </ContentWrap>        <!-- 鏋勬垚楗煎浘 -->       <ContentWrap class="chart-card">         <div class="chart-header">           <div class="chart-header__title">鎴愭湰鏋勬垚鍒嗘瀽</div>           <div class="chart-header__desc">灞曠ず浜у搧鎴愭湰鏋勬垚鍗犳瘮</div>         </div>         <div class="chart-container">           <div ref="compositionChartRef" class="chart-instance"></div>         </div>       </ContentWrap>     </div>      <!-- 瀵规瘮鍥?-->     <ContentWrap class="chart-card chart-card--full">       <div class="chart-header">         <div class="chart-header__title">浜у搧鎴愭湰瀵规瘮</div>         <div class="chart-header__desc">瀵规瘮涓嶅悓浜у搧鍚屼竴鏈熼棿鐨勬垚鏈?/div>       </div>       <div class="chart-container">         <div ref="compareChartRef" class="chart-instance"></div>       </div>     </ContentWrap>      <!-- 鏁版嵁琛ㄦ牸 -->     <ContentWrap class="data-table-card">       <div class="table-header">         <div class="table-header__title">鎴愭湰鏁版嵁鏄庣粏</div>         <div class="table-header__actions">           <el-button type="primary" plain @click="handleExport">             <Icon icon="ep:download" class="mr-5px" /> 瀵煎嚭鎶ヨ〃           </el-button>         </div>       </div>       <el-table :data="tableData" v-loading="loading" stripe class="data-table">         <el-table-column label="鏈熼棿" min-width="100" align="center">           <template #default="{ row }">             <span class="font-mono">{{ row.period }}</span>           </template>         </el-table-column>         <el-table-column label="浜у搧鍚嶇О" min-width="150">           <template #default="{ row }">             <span class="font-semibold">{{ row.productName || '-' }}</span>           </template>         </el-table-column>         <el-table-column label="鍏宠仈宸ュ崟" min-width="120" align="center">           <template #default="{ row }">             <span v-if="row.orderNo" class="font-mono text-blue-600">{{ row.orderNo }}</span>             <span v-else class="text-slate-400">-</span>           </template>         </el-table-column>         <el-table-column label="鐩存帴鏉愭枡" min-width="120" align="right">           <template #default="{ row }">             <span v-if="row.materialCost > 0" class="font-mono">{{ formatMoney(row.materialCost) }}</span>             <span v-else class="text-slate-400 text-xs">鏃犻鏂欒褰?/span>           </template>         </el-table-column>         <el-table-column label="鐩存帴浜哄伐" min-width="120" align="right">           <template #default="{ row }">             <span v-if="row.laborCost > 0" class="font-mono">{{ formatMoney(row.laborCost) }}</span>             <span v-else class="text-slate-400 text-xs">-</span>           </template>         </el-table-column>         <el-table-column label="鎶樻棫" min-width="100" align="right">           <template #default="{ row }">             <span v-if="row.depreciationCost > 0" class="font-mono">{{ formatMoney(row.depreciationCost) }}</span>             <span v-else class="text-slate-400 text-xs">-</span>           </template>         </el-table-column>         <el-table-column label="鐢佃垂" min-width="100" align="right">           <template #default="{ row }">             <span v-if="row.powerCost > 0" class="font-mono">{{ formatMoney(row.powerCost) }}</span>             <span v-else class="text-slate-400 text-xs">-</span>           </template>         </el-table-column>         <el-table-column label="鍏朵粬鍒堕€犺垂" min-width="120" align="right">           <template #default="{ row }">             <span class="font-mono">{{ formatMoney(row.otherCost) }}</span>           </template>         </el-table-column>         <el-table-column label="鎴愭湰鍚堣" min-width="130" align="right">           <template #default="{ row }">             <span class="font-mono font-bold text-red-600">{{ formatMoney(row.totalCost) }}</span>           </template>         </el-table-column>       </el-table>     </ContentWrap>   </div> </template>  <script setup lang="ts"> import { ref, reactive, onMounted, onUnmounted, nextTick } from 'vue' import * as echarts from 'echarts' import request from '@/config/axios'  defineOptions({ name: 'ErpFinanceCostReport' })  const loading = ref(false) const productOptions = ref<any[]>([]) const tableData = ref<any[]>([])  // 鏌ヨ鍙傛暟 const queryParams = reactive({   productId: undefined as number | undefined,   startMonth: '2026-01',   endMonth: '2026-06',   dimension: 'month' })  // 鍥捐〃瀹炰緥 const trendChartRef = ref<HTMLElement>() const compositionChartRef = ref<HTMLElement>() const compareChartRef = ref<HTMLElement>() let trendChart: echarts.ECharts | null = null let compositionChart: echarts.ECharts | null = null let compareChart: echarts.ECharts | null = null  // 瓒嬪娍鏁版嵁 const trendData = ref<any>({})  const formatMoney = (value?: number | string | null) => {   const n = Number(value || 0)   return `楼${n.toLocaleString('zh-CN', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}` }  const formatCount = (value?: number | string | null) => {   const n = Number(value || 0)   if (n === 0) return '-'   return n.toLocaleString('zh-CN', { maximumFractionDigits: 3 }) }  // 鍔犺浇浜у搧鍒楄〃锛堢敤浜庣瓫閫変笅鎷夛級 const loadProductOptions = async () => {   try {     // 鏌ヨ鏈夌敓浜ф垚鏈暟鎹殑浜у搧     const data = await request.get({        url: '/erp/production-cost-entry/product-summary',       params: {}     })     productOptions.value = data || []   } catch (e) {     console.error('鍔犺浇浜у搧鍒楄〃澶辫触', e)   } }  // 鍔犺浇瓒嬪娍鏁版嵁 const loadTrendData = async () => {   const params: any = {     startMonth: queryParams.startMonth,     endMonth: queryParams.endMonth,     dimension: queryParams.dimension   }   if (queryParams.productId) {     params.productId = queryParams.productId   }   const data = await request.get({ url: '/erp/production-cost-entry/cost-trend', params })   trendData.value = data || {}   return data }  const initTrendChart = () => {   if (!trendChartRef.value || !trendData.value.periods) return   trendChart = echarts.init(trendChartRef.value)   const option = {     tooltip: {       trigger: 'axis',       axisPointer: { type: 'shadow' }     },     legend: {       data: ['鐩存帴鏉愭枡', '鐩存帴浜哄伐', '鎶樻棫', '鐢佃垂', '鍏朵粬'],       bottom: 0     },     grid: {       left: '3%',       right: '4%',       bottom: '10%',       top: '5%',       containLabel: true     },     xAxis: {       type: 'category',       data: trendData.value.periods     },     yAxis: {       type: 'value',       axisLabel: {         formatter: (value: number) => `楼${(value / 10000).toFixed(1)}涓嘸       }     },     series: [       {         name: '鐩存帴鏉愭枡',         type: 'line',         stack: 'Total',         areaStyle: { opacity: 0.3 },         emphasis: { focus: 'series' },         data: trendData.value.materialCosts || [],         itemStyle: { color: '#3B82F6' }       },       {         name: '鐩存帴浜哄伐',         type: 'line',         stack: 'Total',         areaStyle: { opacity: 0.3 },         emphasis: { focus: 'series' },         data: trendData.value.laborCosts || [],         itemStyle: { color: '#10B981' }       },       {         name: '鎶樻棫',         type: 'line',         stack: 'Total',         areaStyle: { opacity: 0.3 },         emphasis: { focus: 'series' },         data: trendData.value.depreciationCosts || [],         itemStyle: { color: '#F59E0B' }       },       {         name: '鐢佃垂',         type: 'line',         stack: 'Total',         areaStyle: { opacity: 0.3 },         emphasis: { focus: 'series' },         data: trendData.value.powerCosts || [],         itemStyle: { color: '#06B6D4' }       },       {         name: '鍏朵粬',         type: 'line',         stack: 'Total',         areaStyle: { opacity: 0.3 },         emphasis: { focus: 'series' },         data: trendData.value.otherCosts || [],         itemStyle: { color: '#14B8A6' }       }     ]   }   trendChart.setOption(option) }  const initCompositionChart = () => {   if (!compositionChartRef.value || !trendData.value.compositionData) return   compositionChart = echarts.init(compositionChartRef.value)   const comp = trendData.value.compositionData   const pieData = [     { name: '鐩存帴鏉愭枡', value: Number(comp.materialCost || 0), itemStyle: { color: '#3B82F6' } },     { name: '鐩存帴浜哄伐', value: Number(comp.laborCost || 0), itemStyle: { color: '#10B981' } },     { name: '鎶樻棫', value: Number(comp.depreciationCost || 0), itemStyle: { color: '#F59E0B' } },     { name: '鐢佃垂', value: Number(comp.powerCost || 0), itemStyle: { color: '#06B6D4' } },     { name: '鍏朵粬', value: Number(comp.otherCost || 0), itemStyle: { color: '#14B8A6' } }   ]   const option = {     tooltip: {       trigger: 'item',       formatter: '{a} <br/>{b}: {c} ({d}%)'     },     legend: {       orient: 'vertical',       left: 'left',       top: 'center'     },     series: [       {         name: '鎴愭湰鏋勬垚',         type: 'pie',         radius: ['40%', '70%'],         avoidLabelOverlap: false,         itemStyle: {           borderRadius: 10,           borderColor: '#fff',           borderWidth: 2         },         label: {           show: false,           position: 'center'         },         emphasis: {           label: {             show: true,             fontSize: 16,             fontWeight: 'bold'           }         },         labelLine: {           show: false         },         data: pieData       }     ]   }   compositionChart.setOption(option) }  const initCompareChart = () => {   if (!compareChartRef.value || !trendData.value.productCompareData) return   compareChart = echarts.init(compareChartRef.value)   const compareData = trendData.value.productCompareData   const option = {     tooltip: {       trigger: 'axis',       axisPointer: { type: 'shadow' }     },     legend: {       data: ['鐩存帴鏉愭枡', '鐩存帴浜哄伐', '鍒堕€犺垂鐢?],       bottom: 0     },     grid: {       left: '3%',       right: '4%',       bottom: '10%',       top: '5%',       containLabel: true     },     xAxis: {       type: 'category',       data: compareData.map((item: any) => item.productName || `浜у搧${item.productId}`)     },     yAxis: {       type: 'value',       axisLabel: {         formatter: (value: number) => `楼${(value / 10000).toFixed(1)}涓嘸       }     },     series: [       {         name: '鐩存帴鏉愭枡',         type: 'bar',         stack: 'Total',         emphasis: { focus: 'series' },         data: compareData.map((item: any) => Number(item.materialCost || 0)),         itemStyle: { color: '#3B82F6' }       },       {         name: '鐩存帴浜哄伐',         type: 'bar',         stack: 'Total',         emphasis: { focus: 'series' },         data: compareData.map((item: any) => Number(item.laborCost || 0)),         itemStyle: { color: '#10B981' }       },       {         name: '鍒堕€犺垂鐢?,         type: 'bar',         stack: 'Total',         emphasis: { focus: 'series' },         data: compareData.map((item: any) => Number(item.overheadCost || 0)),         itemStyle: { color: '#F59E0B' }       }     ]   }   compareChart.setOption(option) }  const buildTableData = () => {   if (!trendData.value.periods) return   const periods = trendData.value.periods   const rows: any[] = []    // 濡傛灉娌℃湁閫夋嫨鍏蜂綋浜у搧锛屾寜浜у搧缁村害灞曠ず姣忎釜浜у搧鐨勬暟鎹?  if (!queryParams.productId) {     // 浠巆ompareData涓幏鍙栧悇浜у搧鐨勬暟鎹?    const compareData = trendData.value.productCompareData || []     for (const product of compareData) {       rows.push({         period: `${queryParams.startMonth} ~ ${queryParams.endMonth}`,         productName: product.productName || `浜у搧${product.productId}`,         orderNo: null,         materialCost: Number(product.materialCost || 0),         laborCost: Number(product.laborCost || 0),         depreciationCost: Number(product.overheadCost || 0) * 0.4,         powerCost: Number(product.overheadCost || 0) * 0.3,         otherCost: Number(product.overheadCost || 0) * 0.3,         totalCost: Number(product.materialCost || 0) + Number(product.laborCost || 0) + Number(product.overheadCost || 0)       })     }   } else {     // 閫夋嫨浜嗗叿浣撲骇鍝侊紝灞曠ず璇ヤ骇鍝佹寜鏈堢殑鎴愭湰瓒嬪娍     const orderData = trendData.value.productOrderData || {}     for (let i = 0; i < periods.length; i++) {       const period = periods[i]       const orderInfo = orderData[period] || {}       rows.push({         period: period,         productName: productOptions.value.find(p => p.productId === queryParams.productId)?.productName || `浜у搧${queryParams.productId}`,         orderNo: orderInfo.orderNo || null,         materialCost: trendData.value.materialCosts?.[i] || 0,         laborCost: trendData.value.laborCosts?.[i] || 0,         depreciationCost: trendData.value.depreciationCosts?.[i] || 0,         powerCost: trendData.value.powerCosts?.[i] || 0,         otherCost: trendData.value.otherCosts?.[i] || 0,         totalCost: trendData.value.totalCosts?.[i] || 0       })     }   }   tableData.value = rows }  const handleQuery = () => {   loadData() }  const resetQuery = () => {   queryParams.productId = undefined   queryParams.startMonth = '2026-01'   queryParams.endMonth = '2026-06'   queryParams.dimension = 'month'   loadData() }  const loadData = async () => {   loading.value = true   try {     await loadTrendData()     buildTableData()     await nextTick()     initTrendChart()     initCompositionChart()     initCompareChart()   } catch (e) {     console.error('鍔犺浇鏁版嵁澶辫触', e)   } finally {     loading.value = false   } }  const handleExport = () => {   // TODO: 瀹炵幇瀵煎嚭鍔熻兘   console.log('瀵煎嚭鎶ヨ〃') }  const handleResize = () => {   trendChart?.resize()   compositionChart?.resize()   compareChart?.resize() }  onMounted(() => {   loadProductOptions()   loadData()   window.addEventListener('resize', handleResize) })  onUnmounted(() => {   window.removeEventListener('resize', handleResize)   trendChart?.dispose()   compositionChart?.dispose()   compareChart?.dispose() }) </script>  <style scoped lang="scss"> .cost-report-page {   display: flex;   flex-direction: column;   gap: 16px;   padding: 16px;   background: var(--erp-slate-50);   min-height: 100vh; }  .page-header-card {   .page-header {     display: flex;     justify-content: space-between;     align-items: center;     flex-wrap: wrap;     gap: 12px;   }   .page-header__title {     font-size: 20px;     font-weight: 800;     color: var(--erp-slate-900);   }   .page-header__desc {     margin-top: 4px;     color: var(--erp-slate-500);     font-size: 12px;   }   .page-header__actions {     display: flex;     gap: 12px;     align-items: center;   } }  .filter-card {   .filter-header {     margin-bottom: 16px;   }   .filter-header__title {     font-size: 14px;     font-weight: 600;     color: var(--erp-slate-700);   }   .filter-form {     display: flex;     flex-direction: column;     gap: 16px;   }   .filter-grid {     display: grid;     grid-template-columns: repeat(auto-fill, minmax(200px, 1fr));     gap: 16px;   }   .filter-actions {     display: flex;     justify-content: flex-end;     gap: 8px;   } }  .chart-grid {   display: grid;   grid-template-columns: repeat(2, 1fr);   gap: 16px; }  .chart-card {   &--full {     grid-column: span 2;   } }  .chart-header {   margin-bottom: 16px; }  .chart-header__title {   font-size: 14px;   font-weight: 600;   color: var(--erp-slate-700); }  .chart-header__desc {   font-size: 12px;   color: var(--erp-slate-500);   margin-top: 4px; }  .chart-container {   width: 100%; }  .chart-instance {   width: 100%;   height: 350px; }  .data-table-card {   .table-header {     display: flex;     justify-content: space-between;     align-items: center;     margin-bottom: 16px;   }   .table-header__title {     font-size: 14px;     font-weight: 600;     color: var(--erp-slate-700);   } }  .data-table {   :deep(.el-table__header-wrapper th) {     background: var(--erp-slate-50);     color: var(--erp-slate-600);     font-weight: 600;     font-size: 12px;   } }  @media (max-width: 1024px) {   .chart-grid {     grid-template-columns: 1fr;   }   .chart-card--full {     grid-column: span 1;   } } </style>